public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    visited[start[0]][start[1]] = true;

    if (isReachable(visited, paths, start, end)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean isReachable(boolean[][] visited, int[][] paths, int[] current, int[] end) {
    int rows = paths.length;
    int cols = paths[0].length;

    Queue<int[]> queue = new LinkedList<>();
    queue.offer(current);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        if (x == end[0] && y == end[1]) {
            return true;
        }

        for (int[] dir : new int[][]{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
            int newX = x + dir[0];
            int newY = y + dir[1];

            if (newX >= 0 && newX < rows && newY >= 0 && newY < cols && !visited[newX][newY]) {
                visited[newX][newY] = true;
                queue.offer(new int[]{newX, newY});
            }
        }
    }

    return false;
}
