private int minTimeUtil(int node, Map<Integer, List<Integer>> graph, boolean[] hasApple, boolean[] visited) {
    int time = 0;
    for (int child : graph.get(node)) {
        if (!visited[child]) {
            visited[child] = true;
            if (hasApple[child]) {
                time += 2; // Time to collect an apple
            } else {
                time += minTimeUtil(child, graph, hasApple, visited);
            }
        }
    }
    return time;
}
