public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] squareIndices = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        squareIndices[i] = -1;
    }

    int[] visited = new int[n];
    int ans = 0;
    for (int i = 0; i < n; i++) {
        if (!visit(visited, A[i], squareIndices)) {
            ans += squareRecurrence(squareIndices, A, 0, visited, 0, i);
        }
    }

    return ans;
}

private static boolean visit(int[] visited, int value, int[] squareIndices) {
    for (int i = 0; i <= squareIndices[value]; i++) {
        if (visited[i] == -1) {
            visited[i] = value;
            return true;
        }
    }

    return false;
}

private static int squareRecurrence(int[] squareIndices, int[] A, int start, int[] visited, int sum, int index) {
    if (index == A.length) {
        return sum == 0 ? 1 : 0;
    }

    int prevIndex = -1;
    if (start < A.length - 1) {
        prevIndex = squareIndices[A[start + 1]];
    }

    int ans = 0;
    if (start > 0) {
        if (visited[start - 1] == -1) {
            for (int i = 0; i <= squareIndices[A[start - 1]]; i++) {
                if (start - 1 == prevIndex) {
                    continue;
                }
                visited[start - 1] = i;
                ans += squareRecurrence(squareIndices, A, start + 1, visited, sum + A[start - 1] * A[start + 1], index + 1);
                visited[start - 1] = -1;
            }
        }
    }

    return ans;
}
